//! Parse-path benchmarks — sanity visibility, not a gate.

// Bench harness: fixtures are generated by tests/fixtures/generate_fonts.py;
// assertions legitimately panic here, the lib target stays lint-clean.
#![allow(clippy::unwrap_used, clippy::expect_used, missing_docs)]

use criterion::{criterion_group, criterion_main, Criterion};
use font_parse::FontRef;

const TTF: &[u8] = include_bytes!("../tests/fixtures/minimal.ttf");
#[cfg(feature = "woff2")]
const WOFF2: &[u8] = include_bytes!("../tests/fixtures/minimal.woff2");

fn bench_font_new(c: &mut Criterion) {
    c.bench_function("font_new/sfnt", |b| {
        b.iter(|| FontRef::new(criterion::black_box(TTF)).unwrap())
    });
}

fn bench_cmap_lookup(c: &mut Criterion) {
    let font = FontRef::new(TTF).unwrap();
    let cmap = font.cmap().unwrap();
    c.bench_function("cmap/codepoint", |b| {
        b.iter(|| cmap.codepoint(criterion::black_box('A')).unwrap())
    });
}

fn bench_outline(c: &mut Criterion) {
    let font = FontRef::new(TTF).unwrap();
    c.bench_function("outline/composite", |b| {
        b.iter(|| font.outline(font_parse::GlyphId::new(3)).unwrap().unwrap())
    });
}

#[cfg(feature = "woff2")]
fn bench_woff2_decode(c: &mut Criterion) {
    c.bench_function("woff2/decode", |b| {
        b.iter(|| font_parse::OwnedFont::from_woff2(criterion::black_box(WOFF2)).unwrap())
    });
}

criterion_group!(benches, bench_font_new, bench_cmap_lookup, bench_outline,);
#[cfg(feature = "woff2")]
criterion_group!(benches_woff2, bench_woff2_decode);
#[cfg(feature = "woff2")]
criterion_main!(benches, benches_woff2);
#[cfg(not(feature = "woff2"))]
criterion_main!(benches);
